window.docContents[233].resolve({"/Improper-integrals/3___3-Algebra-and-a-change-of-starting-point/#LMLF-___-DLMF-with-Lean--Improper-integrals--3___3-Algebra-and-a-change-of-starting-point":{"contents":"Finite sums may be formed before integration. Each summand may also be sent through its own\ncontinuous linear map; the exceptional set of the sum is the union of the individual exceptional\nsets, and the value is the corresponding sum of mapped values.\n\n\n\nIf f is integrable on the compact prefix from a to k, moving the starting point from k back\nto a adds precisely that ordinary integral to the improper value.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Improper integrals","header":"3.3 Algebra and a change of starting point","id":"/Improper-integrals/3___3-Algebra-and-a-change-of-starting-point/#LMLF-___-DLMF-with-Lean--Improper-integrals--3___3-Algebra-and-a-change-of-starting-point"}});